seo.schema:
{
    "@context": "https://schema.org",
    "@graph": [
        {
            "@type": "HomeAndConstructionBusiness",
            "@id": "{website}/#localbusiness",
            "name": "{business}",
            "url": "{website}",
            "telephone": "{tel}",
            "image": "{lb_logo}",
            "description": "{business} connects {state} property owners with certified mold inspection and remediation specialists, providing mold testing, black mold removal, safe containment, and moisture control for homes and businesses.",
            "areaServed": {
                "@type": "City",
                "name": "{city}"
            },
            "priceRange": "$$",
            "openingHours": "Mo-Su 00:00-23:59",
            "address": {
                "@type": "PostalAddress",
                "addressLocality": "{city}",
                "addressRegion": "{SS}",
                "postalCode": "{zip}",
                "addressCountry": "US"
            }
        },
        {
            "@type": "WebSite",
            "@id": "{website}/#website",
            "url": "{website}",
            "name": "{business}",
            "publisher": {
                "@id": "{website}/#localbusiness"
            }
        }
    ]
}
